import {createOnlineHost,connectOnline,parseOnlineInvite,onlineInvite} from './online.mjs';
import {CombatRenderer} from './combat.mjs';
import {StoryPath as StoryWorld} from './story.mjs';
import {AudioBus,SILENT_AUDIO} from './audio.mjs';
import {KEY_ACTIONS,defaultBindings,normalizeBindings,bindKey,validKeyCode,actionForKey,movementVector,displayKey} from './controls.mjs';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const TYPES = {Normal:'#b6b9ba',Fire:'#f38c61',Water:'#75b7ec',Electric:'#f7d85e',Grass:'#9ccf79',Ice:'#92ddd7',Fighting:'#dc9273',Poison:'#bf94db',Ground:'#d2b579',Flying:'#a5b5ef',Psychic:'#ed94bb',Bug:'#b9c966',Rock:'#c6b983',Ghost:'#a29acb',Dragon:'#ae9feb',Dark:'#a69a93',Steel:'#a1bec7',Fairy:'#e8b2dc',Stellar:'#aee3ce'};
const ARENAS = [{id:'stadium',name:'Indigo Stadium',subtitle:'The classic center stage',color:'#677997'},{id:'forest',name:'Viridian Grove',subtitle:'Ancient woods · stone cover',color:'#5b956d'},{id:'volcano',name:'Cinder Crater',subtitle:'Molten rock · heated ground',color:'#c37453'},{id:'coast',name:'Azure Coast',subtitle:'Ocean breeze · island arena',color:'#5cacbd'},{id:'ruins',name:'Celestial Ruins',subtitle:'Forgotten stones · close quarters',color:'#8b86a9'},{id:'summit',name:'Frostpeak Summit',subtitle:'Snowy heights · open sightlines',color:'#abc8d6'}];
const STORAGE = 'pokemon-stadium-2d-v1';
let saved = {}; try { saved = JSON.parse(localStorage.getItem(STORAGE) || '{}'); } catch {}
const S = {view:'home',battlePaused:false,user:null,authConfig:{googleConfigured:false},authMode:'login',catalog:null,rules:null,dex:new Map(),moves:{},team:saved.team || [],trainer:saved.trainer || 'Ace',settings:{music:35,effects:70,cries:75,particles:true,screenShake:true,fullscreen:false,...saved.settings},campaign:{stages:[],badges:[],completed:[],unlocked:[]},arena:(saved.arena&&saved.arena!=='island'?saved.arena:'stadium'),lockOn:true,lockTargetTeam:null,selectedSlot:0,brPokemonId:saved.brPokemonId||null,brQuery:'',brGridLimit:48,query:'',typeFilter:'all',gridLimit:72,socket:null,connected:false,serverOrigin:location.origin,room:null,inviteOrigin:null,pendingInvite:null,battle:null,snapshot:null,previousSnapshot:null,lastSnapshot:0,selfTeam:0,input:{dx:0,dy:0,aimX:950,aimY:380,cast:null,dodge:false,switch:null},seq:0,keys:new Set(),mouse:{x:950,y:380,active:false},controller:false,padLast:[],padNavAt:0,padEditing:false,gamepadAim:{x:1,y:0},lastHud:0,lastRender:0,sprites:new Map(),seenEvents:new Set(),particles:[],rings:[],labels:[],shake:0,battleStarted:0,resultShown:false,latency:0,lastNotice:0,reconnectTimer:0,connectionEpoch:0};
S.settings.bindings=normalizeBindings(S.settings.bindings);
let bindingCapture=null,controlsReturn='settings',onlineHost=null,onlineRoomCode=null,onlineReady=false,onlineStatus='CONNECTING ONLINE…';
function closeOnlineRoom(){onlineRoomCode=null;onlineReady=false;onlineHost?.close();onlineHost=null;}
async function openOnlineRoom(room){if(!room?.host||onlineRoomCode===room.code)return;closeOnlineRoom();onlineRoomCode=room.code;onlineStatus='CONNECTING ONLINE…';const code=room.code;try{const host=await createOnlineHost({code,token:room.token,onStatus:status=>{if(onlineRoomCode!==code)return;onlineStatus=status;if(S.room&&!S.battle)renderLobby();}});if(onlineRoomCode!==code){host.close();return;}onlineHost=host;onlineReady=true;onlineStatus='ONLINE · SHARE YOUR CODE';if(S.room&&!S.battle)renderLobby();}catch(error){if(onlineRoomCode!==code)return;onlineStatus=error.message;onlineReady=false;if(S.room&&!S.battle)renderLobby();toast(error.message,7000);}}

const AUDIO=new AudioBus(()=>S.settings,id=>S.dex.get(id));
Object.assign(S,{intro:true,inputReadyAt:0,storyData:null,storyActive:false,dialogue:null,storyReturn:null,worldInput:{x:0,y:0},demo:null,demoSocket:null,demoTimer:0});
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({team:S.team,trainer:S.trainer,settings:S.settings,arena:S.arena,brPokemonId:S.brPokemonId}));}catch{}}
function mon(id){return S.dex.get(typeof id==='string'?id:id?.species) || S.catalog?.species?.[0];}
function color(type){return TYPES[type] || '#ddd5a9';}
function chips(types){return (types||[]).map(t=>`<span class="type-chip" style="--type:${color(t)}">${esc(t)}</span>`).join(' ');}
function imageMon(species,classes='',extra=''){const p=mon(species);return p?`<img src="${esc(p.sprite)}" alt="${esc(p.name)}" class="${classes}" draggable="false" ${extra}>`:'';}
function normalizeTeam(){S.team = (S.team.length?S.team:[{species:'pikachu'},{species:'charizard'},{species:'greninja'}]).slice(0,3).map(t=>{const p=mon(t.species);const valid=(t.moves||p.moves||[]).filter((m,i,a)=>S.moves[m]&&(p.learnset||p.moves).includes(m)&&a.indexOf(m)===i).slice(0,4);return{species:p.id,moves:valid.length?valid:[...p.moves]};});while(S.team.length<3){const p=mon(['lucario','gengar','blastoise'][S.team.length]);S.team.push({species:p.id,moves:[...p.moves]});}persist();}
function toast(message,duration=3500){const el=$('#toast');el.textContent=String(message).slice(0,230);el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),duration);}
function notice(text,type='Normal'){const e=$('#combat-notice');e.textContent=String(text).slice(0,100);e.style.color=color(type);e.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>e.classList.remove('show'),1700);}
function loading(){ $('#main').innerHTML='<div class="loading-screen"><div class="loading-ball"></div><h2>PREPARING YOUR JOURNEY</h2><p>Opening the National Dex and checking your team…</p></div>'; }
function pageHeading(title,subtitle,extra=''){return `<button class="back-button" data-view="home">← MAIN MENU</button><div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function teamSummary(){return S.team.map(t=>{const p=mon(t);return `<div class="summary-mon">${imageMon(p.id)}<div><strong>${esc(p.name)}</strong><small>${p.types.map(esc).join(' / ')} · ${t.moves.length} MOVES</small></div></div>`;}).join('');}
function updateNav(){for(const a of $('.top-link'))a.classList.toggle('active',a.dataset.view===S.view);$('#trainer-name').textContent=S.user?.displayName||S.trainer;$('#profile-button .profile-label').textContent=S.user?'ACCOUNT':'TRAINER';const avatar=$('#profile-avatar');if(S.user?.avatar){avatar.classList.add('has-image');avatar.innerHTML='<img src="'+esc(S.user.avatar)+'" alt="Profile picture">';}else{avatar.classList.remove('has-image');avatar.textContent=(S.user?.displayName||S.trainer||'A').charAt(0).toUpperCase();}}
function render(view=S.view){if(!S.catalog)return;if(!['home','royale','settings'].includes(view))view='home';bindingCapture=null;clearInputs();if(S.storyActive){storyWorld.savePosition(true);storyWorld.setActive(false);S.storyActive=false;}S.view=view;S.padEditing=false;updateNav();$('#app').classList.remove('hidden');$('#story').classList.add('hidden');if(!S.battle)$('#battle').classList.add('hidden');$('#menu-atmosphere').classList.toggle('hidden',view!=='home');const renderers={home:renderHome,royale:renderRoyale,settings:renderSettings};(renderers[view]||renderHome)();$('#main').scrollTop=0;AUDIO.setContext('menu');stopDemo();if(S.controller)setTimeout(()=>focusFirst(),50);}
function renderHome(){$('#main').innerHTML=`<section class="empress-home royale-home"><div class="home-copy"><div class="empress-subtitle">THE SURVIVAL ARENA</div><h1 class="empress-title">Pokemon<br>Battle Royale</h1><p class="empress-description">Choose your first-stage Pokémon. Defeat rivals, earn experience, evolve, and be the last one standing.</p><div class="menu-list"><button class="menu-entry primary" data-view="royale"><span class="menu-icon">♛</span><span class="menu-title">ENTER BATTLE ROYALE<span class="menu-description">12 Pokémon · One survivor · Evolve as you win</span></span><span class="menu-arrow">→</span></button></div><div class="home-controls"><span><b>Ⓐ</b> SELECT &nbsp; <b>Ⓑ</b> BACK</span><span><b>↕</b> NAVIGATE</span></div></div><div class="menu-observer"><div class="exhibition-label"><i class="live-pip"></i> LAST MON STANDING <strong>12 enter. One wins.</strong><span>Survive the arena. Become a champion.</span></div><div class="team-preview"><div class="section-eyebrow">YOUR PATH TO VICTORY</div><div class="preview-team"><div class="preview-mon"><div><strong>01 · CHOOSE</strong><small>Pick a Pokémon that can evolve</small></div></div><div class="preview-mon"><div><strong>02 · ELIMINATE</strong><small>Every knockout earns experience</small></div></div><div class="preview-mon"><div><strong>03 · EVOLVE</strong><small>Grow stronger during the match</small></div></div></div></div></div></section>`;}
function renderQuick(){$('#main').innerHTML=`<section class="page">${pageHeading('PICK YOUR BATTLEGROUND.','A fast, full-team match against a CPU trainer. Movement and timing win battles.','<span class="pill">3 vs 3 · REAL-TIME</span>')}<div class="quick-layout"><div><div class="section-eyebrow">SIX PLACES TO MAKE YOUR MARK</div><div class="arena-options">${ARENAS.map(a=>`<button class="arena-card ${S.arena===a.id?'active':''}" data-arena="${a.id}" style="background-color:${a.color};background-image:url('/assets/arenas/${a.id}.png')"><strong>${a.name}</strong><span>${a.subtitle}</span></button>`).join('')}</div><div class="intro-panel" style="margin-top:23px"><div><h2>READ THE ROOM. FIND YOUR OPENING.</h2><p>Move to face your opponent, attack in that direction, and dodge incoming moves. Switch Pokémon to use type advantages. Your moves have their canonical PP and their own arena cooldowns. Empty move slots become Struggle, a close-range attack with recoil. Pick up a violet PP orb to restore 1 PP to one move. Attack windups, recoveries, and hit reactions create openings.</p></div></div></div><aside class="battle-summary"><h2>YOUR LINEUP</h2>${teamSummary()}<button class="primary-button" id="start-quick">ENTER THE ARENA ↗</button><button class="secondary-button" data-view="team" style="width:100%;margin-top:10px">EDIT TEAM</button><p class="legal-note">${S.controller?'LEFT STICK move & face<br>A / X / Y / B attack · RT dodge':`${esc(keyLabel('up'))}/${esc(keyLabel('left'))}/${esc(keyLabel('down'))}/${esc(keyLabel('right'))} move & face<br>${[1,2,3,4].map(i=>esc(keyLabel(`move${i}`))).join(' / ')} attack · ${esc(keyLabel('dodge'))} dodge`}</p></aside></div></section>`;}
function renderRoyale(){if(!ARENAS.some(a=>a.id===S.arena))S.arena='stadium';const firstStarter=S.catalog.species.find(p=>p.battleRoyaleStarter);if(!S.brPokemonId||!S.dex.has(S.brPokemonId)||!mon(S.brPokemonId)?.battleRoyaleStarter)S.brPokemonId=firstStarter?.id||'bulbasaur';const picked=mon(S.brPokemonId);$('#main').innerHTML=`<section class="page royale-page">${pageHeading('ONE POKÉMON. ELEVEN RIVALS.','Choose a Pokémon in its first form. Eliminate rivals to gain levels and evolve during the match.','<span class="pill">12 COMBATANTS · LAST MON STANDING</span>')}<div class="quick-layout royale-layout"><div class="team-catalog"><div class="searchbar"><input id="br-pokemon-search" type="search" placeholder="Search first-stage Pokémon…" value="${esc(S.brQuery)}" aria-label="Search Battle Royale starter Pokémon"></div><div id="br-catalog-results"></div></div><aside class="battle-summary royale-summary"><div class="section-eyebrow">YOUR BATTLE ROYALE STARTER</div><div class="royale-starter" style="--type:${color(picked.types[0])}">${imageMon(picked.id)}<div><h2>${esc(picked.name)}</h2>${chips(picked.types)}</div></div><p>All Pokémon start at level 5. Earn 60 XP per elimination. Your first evolution unlocks at level 8; later evolutions need three more levels. Each attack is capped so no single hit can knock you out.</p><div class="field"><label for="br-arena">ARENA</label><select id="br-arena">${ARENAS.map(a=>`<option value="${a.id}" ${a.id===S.arena?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="royale-rules"><span>⚔ 11 balanced CPU rivals</span><span>✦ First forms only</span><span>↑ XP from eliminations</span><span>♜ Last survivor wins</span></div><button class="primary-button" id="start-royale">ENTER BATTLE ROYALE ↗</button><p class="legal-note">${S.controller?'LEFT STICK move · A/X/Y/B attack · RT dodge':`${esc(keyLabel('up'))}/${esc(keyLabel('left'))}/${esc(keyLabel('down'))}/${esc(keyLabel('right'))} move · ${[1,2,3,4].map(i=>esc(keyLabel(`move${i}`))).join('/')} attack · ${esc(keyLabel('dodge'))} dodge`}</p></aside></div></section>`;renderRoyaleCatalog();}
function renderRoyaleCatalog(){const q=S.brQuery.trim().toLowerCase(),matches=S.catalog.species.filter(p=>p.battleRoyaleStarter&&(!q||p.name.toLowerCase().includes(q)||String(p.num)===q||p.id.includes(q)));$('#br-catalog-results').innerHTML=`<div class="catalog-count">${matches.length.toLocaleString()} STARTERS AVAILABLE · PICK ONE</div><div class="pokemon-grid royale-grid">${matches.slice(0,S.brGridLimit).map(p=>`<button class="pokemon-card ${S.brPokemonId===p.id?'chosen':''}" data-br-pokemon="${esc(p.id)}"><span class="dex">#${String(p.num).padStart(3,'0')}</span>${imageMon(p.id,'','loading="lazy"')}<strong>${esc(p.name)}</strong><small>${p.types.map(esc).join(' / ')}</small></button>`).join('')}</div>${!matches.length?'<div class="empty-state">No Pokémon match that search.</div>':''}${matches.length>S.brGridLimit?'<button class="secondary-button load-more" id="br-load-more">SHOW MORE POKÉMON ↓</button>':''}`;}
function renderTeam(){const selected=mon(S.team[S.selectedSlot]);$('#main').innerHTML=`<section class="page team-page">${pageHeading('BUILD YOUR THREE.','Your lineup, your play style. Select a slot, then choose any Pokémon or form.',`<span class="pill">${S.catalog.stats?.nationalSpecies||1025} POKÉMON + ${S.catalog.stats?.forms||0} FORMS</span>`)}<div class="team-layout"><aside class="team-roster">${S.team.map((t,i)=>{const p=mon(t);return `<button class="roster-card ${i===S.selectedSlot?'selected':''}" data-slot="${i}"><span class="slot-label">0${i+1}</span>${imageMon(p.id)}<div><h3>${esc(p.name)}</h3>${chips(p.types)}</div></button>`;}).join('')}<div class="team-note">Select a Pokémon to replace slot ${S.selectedSlot+1}. Your team saves automatically.</div><div class="selected-detail"><div class="detail-title"><span>${esc(selected.name)}</span><span style="color:var(--muted)">#${String(selected.num).padStart(3,'0')}</span></div><div class="stats">${Object.entries(selected.baseStats).map(([key,val])=>`<div class="stat-row"><span>${key.toUpperCase()}</span><i><b style="width:${val/255*100}%"></b></i><span>${val}</span></div>`).join('')}</div><div class="preset-moves">${S.team[S.selectedSlot].moves.map((id,i)=>{const m=S.moves[id];return `<button class="preset-move" data-edit-move="${i}" title="Choose a legal supported move">${chips([m.type])}<span>${esc(m.name)}</span><small>${m.pp} PP ↗</small></button>`;}).join('')}</div><div class="ability-line">Battle animation: <b>${combat.manifest[selected.id]?.walk?'8-direction authored sprites':'Runtime action animation'}</b><br>Ability: <b>${esc(selected.abilities?.['0']||'—')}</b><br>${abilitySupported(selected.abilities?.['0'])?'Active in arena battles':'Displayed only · effect not implemented'}</div><p class="legal-note">Select a move to customize it. Legal learnsets, base stats and type matchups.</p><button class="rules-link" id="arena-rules">ARENA RULES & SUPPORTED EFFECTS ↗</button></div></aside><div class="team-catalog"><div class="searchbar"><input id="pokemon-search" type="search" placeholder="Search name, Pokédex number, or form…" value="${esc(S.query)}" aria-label="Search Pokémon"><select id="type-filter" aria-label="Filter by type"><option value="all">All types</option>${Object.keys(TYPES).map(t=>`<option value="${t}" ${S.typeFilter===t?'selected':''}>${t}</option>`).join('')}</select></div><div id="catalog-results"></div></div></div></section>`;renderCatalog();}
function renderCatalog(){const q=S.query.trim().toLowerCase();const matches=S.catalog.species.filter(p=>(S.typeFilter==='all'||p.types.includes(S.typeFilter))&&(!q||p.name.toLowerCase().includes(q)||String(p.num)===q||p.id.includes(q)));$('#catalog-results').innerHTML=`<div class="catalog-count">${matches.length.toLocaleString()} AVAILABLE · CHOOSING SLOT ${S.selectedSlot+1}</div><div class="pokemon-grid">${matches.slice(0,S.gridLimit).map(p=>`<button class="pokemon-card ${S.team.some(t=>t.species===p.id)?'chosen':''}" data-pokemon="${esc(p.id)}"><span class="dex">#${String(p.num).padStart(3,'0')}</span>${imageMon(p.id,'','loading="lazy"')}<strong>${esc(p.name)}</strong><small>${p.types.map(esc).join(' / ')}</small></button>`).join('')}</div>${!matches.length?'<div class="empty-state">No Pokémon match that search.</div>':''}${matches.length>S.gridLimit?'<button class="secondary-button load-more" id="load-more">SHOW MORE POKÉMON ↓</button>':''}`;}
function editMove(slot){const p=mon(S.team[S.selectedSlot]),current=S.team[S.selectedSlot].moves[slot];const options=(p.learnset||p.moves).filter(id=>S.moves[id]&&(id===current||!S.team[S.selectedSlot].moves.includes(id))).map(id=>S.moves[id]).sort((a,b)=>a.name.localeCompare(b.name));openModal(`<div class="result-sub">${esc(p.name.toUpperCase())} · MOVE ${slot+1}</div><h2>MAKE YOUR MOVE.</h2><p>Choose from ${esc(p.name)}'s supported legal moves. Power, accuracy, PP, type, and category use the canonical data.</p><div class="field"><label for="move-select">MOVE</label><select id="move-select">${options.map(m=>`<option value="${m.id}" ${m.id===current?'selected':''}>${esc(m.name)} · ${esc(m.type)} · ${m.category==='Status'?'Status':m.basePower+' power'} · ${m.pp} PP</option>`).join('')}</select></div><p id="move-description"></p><p class="legal-note">Real-time adaptation: attacks use facing, range, collision, PP, and cooldowns. Status durations and move timing follow arena rules. ${S.catalog.stats?.supportedMoves||181} moves are supported across the roster.</p><div class="modal-actions"><button class="secondary-button" data-close-modal>CANCEL</button><button class="primary-button" id="save-move">EQUIP MOVE</button></div>`);const desc=()=>{const m=S.moves[$('#move-select').value];$('#move-description').textContent=m.shortDesc||m.description||'';};desc();$('#move-select').addEventListener('change',desc);$('#save-move').onclick=()=>{S.team[S.selectedSlot].moves[slot]=$('#move-select').value;persist();closeModal();renderTeam();toast('Move equipped.');};}
function renderCircuit(){enterStory();}
function renderPrivate(){if(S.room){renderLobby();return;}$('#main').innerHTML=`<section class="page page-narrow">${pageHeading('SETTLE IT IN THE ARENA.','Your friend. Your teams. One live battle.')}<div class="private-layout"><div class="panel"><div class="panel-icon">⌘</div><h2>HOST A PRIVATE BATTLE</h2><p>Create a room, share your invite, and battle as soon as your friend joins. Your code works over the internet. Both trainers need this updated Empress game.</p><div class="field"><label for="private-arena">BATTLEGROUND</label><select id="private-arena">${ARENAS.map(a=>`<option value="${a.id}" ${a.id===S.arena?'selected':''}>${a.name}</option>`).join('')}</select></div><button class="primary-button" id="create-room">CREATE A ROOM ↗</button></div><div class="panel"><div class="panel-icon">↗</div><h2>JOIN YOUR FRIEND</h2><p>Paste the complete private invite your friend shared. Check your lineup before joining: the match starts when both trainers are in the room.</p><div class="field"><label for="invite-input">PRIVATE ONLINE CODE OR INVITE LINK</label><input id="invite-input" placeholder="EMPRESS1:CODE:private-token" value="${esc(S.pendingInvite?.url||'')}" autocomplete="off" spellcheck="false"></div><button class="primary-button" id="join-room">JOIN BATTLE ↗</button><button class="secondary-button" data-view="team">CHECK YOUR TEAM</button></div></div><p class="legal-note">Private matches use a live connection to the host. Leave the host game open during your match. Paste the complete online code into Private Battle in the updated game. Internet play uses a signaling service and an encrypted direct or relay connection.</p></section>`;}
function inviteUrl(){return S.room?onlineInvite(S.room):'';}
function renderLobby(){const r=S.room;$('#main').innerHTML=`<section class="page page-narrow">${pageHeading('YOUR ROOM IS OPEN.','Share your private online code. Keep the host game open; the battle begins when your friend joins.')}<div class="panel"><div class="section-eyebrow">PRIVATE ROOM · ${esc(ARENAS.find(a=>a.id===S.arena)?.name||'STADIUM')}</div><div class="lobby-code">${esc(r.code)}</div><div class="lobby-players"><div class="lobby-player"><strong>${esc(r.players?.[0]?.name||S.trainer)}</strong><span>✓ READY TO BATTLE</span></div><div class="lobby-player"><strong>${esc(r.players?.[1]?.name||'Waiting for a challenger…')}</strong><span><i class="waiting-pulse"></i>INVITE YOUR FRIEND</span></div></div><div class="field"><label for="room-invite">PRIVATE ONLINE CODE</label><div class="invite-row"><input id="room-invite" readonly value="${esc(inviteUrl())}"><button class="secondary-button" id="copy-invite" ${!onlineReady?'disabled':''}>COPY ONLINE CODE</button></div></div><p class="online-status" role="status">${esc(onlineStatus)}</p>${!onlineReady?'<button class="secondary-button" id="retry-online">RETRY ONLINE</button>':''}<button class="secondary-button" id="leave-room">CLOSE ROOM</button><p>Your friend pastes this entire code into Private Battle in their updated Empress game. Both games must stay open during the match.</p></div></section>`;}
function parseInvite(value){if(/^EMPRESS1:|^empress:/i.test(value.trim()))return parseOnlineInvite(value);try{const url=new URL(value.trim());if(!['http:','https:'].includes(url.protocol))throw new Error();const h=new URLSearchParams(url.hash.replace(/^#/,''));const code=h.get('join')||h.get('code')||url.searchParams.get('code')||url.searchParams.get('room'),token=h.get('token')||url.searchParams.get('token');if(!code||!token)throw new Error();return{origin:url.origin,code,token,url:url.href};}catch{throw new Error('Paste the complete invite link, including its room code and private token.');}}
async function joinRoom(){try{const invite=parseInvite($('#invite-input').value);const button=$('#join-room');button.disabled=true;button.textContent='CONNECTING…';closeOnlineRoom();await connect(invite.online?invite:invite.origin);S.pendingInvite=null;send({type:'joinRoom',code:invite.code,token:invite.token,team:S.team});}catch(e){toast(e.message);renderPrivate();}}
async function createRoom(){closeOnlineRoom();const arena=$('#private-arena').value;S.arena=arena;persist();try{await connect(location.origin);send({type:'createRoom',team:S.team,arena});}catch(e){toast(e.message);}}
async function copyInvite(){try{if(window.stadium)await window.stadium.copyText(inviteUrl());else await navigator.clipboard.writeText(inviteUrl());toast('Private invite copied.');}catch{const input=$('#room-invite');input.focus();input.select();toast('Select and copy the highlighted invite.');}}
function renderSettings(){$('#main').innerHTML=`<section class="page page-narrow">${pageHeading('MAKE YOURSELF AT HOME.','Tune the sound, find your controls, and get ready to battle.')}<div class="settings-layout"><div class="panel"><h2>SOUND & DISPLAY</h2>${[['music','Music','Recorded Pokémon game soundtrack'],['effects','Battle effects','Attacks, impacts and menu sounds'],['cries','Pokémon cries','Species cries on entry and switching']].map(([id,title,desc])=>`<div class="setting-row"><div>${title}<small>${desc}</small></div><input type="range" min="0" max="100" value="${S.settings[id]}" data-setting="${id}" aria-label="${title}"></div>`).join('')}${[['particles','Battle particles','Type-colored trails, sparks and impact rings'],['screenShake','Impact shake','Subtle camera response on hits'],...(window.stadium?[['fullscreen','Fullscreen','Fill your display for an immersive arena']]:[])].map(([id,title,desc])=>`<div class="setting-row"><div>${title}<small>${desc}</small></div><button class="switch-button ${S.settings[id]?'on':''}" data-toggle="${id}" role="switch" aria-checked="${S.settings[id]}" aria-label="${title}"></button></div>`).join('')}<button class="secondary-button" id="edit-profile">EDIT TRAINER NAME</button></div><div class="panel"><h2>READY, PLAYER ONE.</h2><div class="controller-diagram"><span class="pad-key a">A</span><span class="pad-key x">X</span><span class="pad-key y">Y</span><span class="pad-key b">B</span></div><div class="section-eyebrow">XBOX / STANDARD GAMEPAD</div>${[['Move & face','LEFT STICK'],['Moves 1 / 2 / 3 / 4','A / X / Y / B'],['Dodge','RT'],['Switch Pokémon','LB / RB'],['Battle menu','MENU'],['Menu select / back','A / B']].map(([a,b])=>`<div class="control-row"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}<div class="section-eyebrow" style="margin-top:24px">KEYBOARD + MOUSE</div>${[['Move & face',[keyLabel('up'),keyLabel('left'),keyLabel('down'),keyLabel('right')].join(' / ')],['Moves 1 / 2 / 3 / 4',[1,2,3,4].map(i=>keyLabel(`move${i}`)).join(' / ')],['First attack','LEFT MOUSE'],['Dodge / switch',`${keyLabel('dodge')} / ${keyLabel('previous')} or ${keyLabel('next')}`],['Story visit',keyLabel('interact')],['Menu / back','ESC']].map(([a,b])=>`<div class="control-row"><span>${a}</span><kbd>${esc(b)}</kbd></div>`).join('')}<button class="secondary-button" id="edit-controls">CHANGE KEYBINDS</button></div></div><p class="legal-note">An unofficial, noncommercial fan project. Pokémon characters, names, artwork and sounds belong to their respective owners. Canonical data and sprite sources: <a href="https://pokemonshowdown.com/credits" target="_blank" rel="noopener">Pokémon Showdown and its credited artists</a>. Arena rules adapt supported moves to real-time play; abilities and move effects are limited to the implemented ruleset.</p></section>`;}
function abilitySupported(name){const id=String(name||'').toLowerCase().replace(/[^a-z0-9]/g,'');return S.rules?.supportedAbilities?.includes(id)||false;}
function showRules(){openModal(`<div class="result-sub">KNOW YOUR ARENA</div><h2>THE RULES OF PLAY.</h2><p>All Pokémon use level 50, neutral nature, 31 IVs, and zero EVs. Base stats, types, STAB, effectiveness, move power, accuracy, category, and PP use canonical data. Attack damage uses a ${Math.round((S.rules?.arenaDamageScale??.18)*100)}% arena multiplier for longer real-time fights.</p><p><b>${S.catalog.stats?.supportedMoves||181} supported moves.</b> The selector contains supported legal moves for that Pokémon. Projectiles, melee range, dodging, cooldowns, flinching, counters, and status durations are real-time adaptations.</p><p>Supported abilities are active; other abilities are labeled inactive. Held items, weather, terrain, in-battle Mega Evolution, Z-Moves, Dynamax, and Terastallization are not implemented. Alternate forms can be selected as starting Pokémon.</p><p>Story challenges are checkpoint battles. Your team is fully healed for each challenge. Private matches are three-on-three, with online codes for internet play. Empty move slots use Struggle with recoil; violet orbs restore 1 PP to one move.</p><div class="modal-actions"><button class="primary-button" data-close-modal>READY TO BATTLE</button></div>`,true);}
function readImageData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Could not read that image.'));reader.readAsDataURL(file);});}
function openAccountModal(mode=S.authMode){
  if(S.user){openProfileModal();return;}
  openAuthModal(mode||'login');
}
function openAuthModal(mode='login',error=''){
  S.authMode=mode==='register'?'register':'login';
  const register=S.authMode==='register',google=S.authConfig.googleConfigured;
  const html=[
    '<div class="auth-heading"><div class="auth-emblem">♛</div><div><div class="result-sub">POKÉMON BATTLE ROYALE</div><h2>'+(register?'CREATE YOUR ACCOUNT':'WELCOME BACK')+'</h2></div></div>',
    '<p>Save your trainer identity, name and profile picture across sessions.</p>',
    '<button id="auth-google" class="google-auth-button" '+(google?'':'disabled')+'><span class="google-mark">G</span><span>Continue with Google</span><span class="auth-arrow">→</span></button>',
    google?'':'<div class="auth-hint">Google sign-in needs OAuth credentials in the server configuration. Email sign-in is available now.</div>',
    '<div class="auth-divider"><span>OR CONTINUE WITH EMAIL</span></div>',
    '<div class="auth-tabs"><button type="button" data-auth-mode="login" class="'+(!register?'active':'')+'">SIGN IN</button><button type="button" data-auth-mode="register" class="'+(register?'active':'')+'">CREATE ACCOUNT</button></div>',
    '<form id="auth-form" data-mode="'+S.authMode+'">',
    register?'<div class="field"><label for="auth-name">TRAINER NAME</label><input id="auth-name" name="displayName" maxlength="24" autocomplete="nickname" required placeholder="Choose your trainer name" value="'+esc(S.trainer)+'"></div>':'',
    '<div class="field"><label for="auth-email">EMAIL ADDRESS</label><input id="auth-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@gmail.com"></div>',
    '<div class="field"><label for="auth-password">PASSWORD</label><input id="auth-password" name="password" type="password" autocomplete="'+(register?'new-password':'current-password')+'" minlength="8" maxlength="128" required placeholder="'+(register?'At least 8 characters':'Your password')+'"></div>',
    register?'<div class="field"><label for="auth-confirm">CONFIRM PASSWORD</label><input id="auth-confirm" name="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="Enter your password again"></div>':'',
    '<div id="auth-error" class="auth-error" role="alert">'+esc(error)+'</div>',
    '<button class="primary-button auth-submit" type="submit">'+(register?'CREATE ACCOUNT':'SIGN IN')+' <span>→</span></button>',
    '</form>',
    '<div class="auth-legal">By continuing, your account details are stored by the game server. Never reuse a password from another site.</div>'
  ].join('');
  openModal(html,true);
  $('#auth-email')?.focus();
}
function openProfileModal(error=''){
  if(!S.user){openAuthModal('login');return;}
  const avatar=S.user.avatar||'',preview=avatar?'<img src="'+esc(avatar)+'" alt="Current profile picture">':'<span>'+(esc(S.user.displayName||'A').charAt(0).toUpperCase())+'</span>';
  const provider=S.user.provider==='google'?'GOOGLE ACCOUNT':S.user.provider==='google+email'?'GOOGLE + EMAIL':'EMAIL ACCOUNT';
  const html=[
    '<div class="auth-heading"><div class="auth-emblem">♛</div><div><div class="result-sub">'+provider+'</div><h2>TRAINER PROFILE</h2></div></div>',
    '<p>Customize the name and picture other trainers see.</p>',
    '<form id="profile-form">',
    '<div class="profile-edit-avatar"><div id="profile-photo-preview" class="profile-photo-preview">'+preview+'</div><div class="profile-photo-copy"><label for="profile-photo">PROFILE PICTURE</label><input id="profile-photo" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP · up to 256 KB</small>'+(avatar?'<label class="avatar-remove"><input id="profile-photo-remove" type="checkbox"> Remove picture</label>':'')+'</div></div>',
    '<div class="field"><label for="profile-name">TRAINER NAME</label><input id="profile-name" name="displayName" maxlength="24" required value="'+esc(S.user.displayName)+'"></div>',
    '<div class="field"><label for="profile-email">EMAIL ADDRESS</label><input id="profile-email" type="email" readonly value="'+esc(S.user.email)+'"></div>',
    '<div id="profile-error" class="auth-error" role="alert">'+esc(error)+'</div>',
    '<button class="primary-button auth-submit" type="submit">SAVE PROFILE <span>→</span></button>',
    '</form>',
    '<div class="modal-actions"><button type="button" class="secondary-button" id="auth-logout">SIGN OUT</button><button type="button" class="secondary-button" data-close-modal>CLOSE</button></div>'
  ].join('');
  openModal(html,true);
}
function editProfile(){openAccountModal();}
async function signOutAccount(){
  try{await fetch('/api/auth/logout',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});}catch{}
  S.user=null;S.trainer=saved.trainer||'Ace';persist();send({type:'hello',name:S.trainer});closeModal();updateNav();toast('You have signed out.');
}
function showAuthRedirectNotice(){
  const params=new URLSearchParams(location.search),status=params.get('auth'),failure=params.get('authError');
  if(status==='success')toast('Google sign-in complete. Welcome!');
  const messages={google_not_configured:'Google sign-in is not configured yet. Add your OAuth credentials to codigo-extraido/.env.',google_cancelled:'Google sign-in was cancelled.',google_state:'Sign-in expired or failed its security check. Please try again.',google_failed:'Google could not sign you in. Check the OAuth configuration and try again.'};
  if(failure)toast(messages[failure]||'Sign-in failed. Please try again.',4500);
  if(status||failure)history.replaceState(null,'',location.pathname+location.hash);
}
function keyLabel(action,index=0){return displayKey(S.settings.bindings[action]?.[index]);}
function keyboardHints(){return `${esc([keyLabel('up'),keyLabel('left'),keyLabel('down'),keyLabel('right')].join('/'))} MOVE & FACE <span>·</span> ${esc([1,2,3,4].map(i=>keyLabel(`move${i}`)).join('/'))} ATTACK <span>·</span> ${esc(keyLabel('dodge'))} DODGE <span>·</span> ${esc(keyLabel('previous'))}/${esc(keyLabel('next'))} SWITCH`;}
function clearInputs(){S.keys.clear();S.input.dx=0;S.input.dy=0;S.input.cast=null;S.input.dodge=false;S.input.switch=null;S.worldInput={x:0,y:0};}
function controlsModal(returnTo=controlsReturn){controlsReturn=returnTo;bindingCapture=null;openModal(`<div class="result-sub">EMPRESS · YOUR CONTROLS</div><h2>MAKE YOUR MOVE.</h2><p>Select a key, then press its replacement. Shared keys swap automatically. Escape cancels a change and always opens or closes menus.</p><div class="keybindings">${KEY_ACTIONS.map(action=>`<div class="binding-row"><span>${esc(action.label)}</span><div>${S.settings.bindings[action.id].map((code,index)=>`<button class="secondary-button binding-key" data-bind-action="${action.id}" data-bind-index="${index}" aria-label="Change ${esc(action.label)} key ${index+1}">${esc(displayKey(code))}</button>`).join('')}</div></div>`).join('')}</div><p class="binding-status" id="binding-status" role="status">Changes save automatically. The mouse and gamepad keep their usual controls.</p><div class="modal-actions"><button class="secondary-button" id="reset-controls">RESET DEFAULTS</button><button class="secondary-button hidden" id="cancel-binding">CANCEL CHANGE</button><button class="primary-button" id="controls-return">DONE</button></div>`,true);}
function cancelBinding(message='Key change cancelled.'){bindingCapture=null;clearInputs();for(const button of $$('[data-bind-action]')){button.classList.remove('listening');button.textContent=keyLabel(button.dataset.bindAction,+button.dataset.bindIndex);}$('#cancel-binding')?.classList.add('hidden');const status=$('#binding-status');if(status)status.textContent=message;}
function captureBinding(action,index){cancelBinding('');bindingCapture={action,index};clearInputs();const button=$(`[data-bind-action="${action}"][data-bind-index="${index}"]`);button?.classList.add('listening');if(button)button.textContent='PRESS KEY';$('#cancel-binding')?.classList.remove('hidden');$('#binding-status').textContent=`Press a key for ${KEY_ACTIONS.find(item=>item.id===action).label.toLowerCase()}. Escape cancels.`;}
function returnFromControls(){const destination=controlsReturn;closeModal(destination!=='battle');if(destination==='battle'&&S.battle&&!S.resultShown)battleMenu();else if(destination==='story'&&S.storyActive)storyMenu();else if(!S.battle&&!S.storyActive)renderSettings();}
function openModal(html,wide=false){bindingCapture=null;$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${html}</div></div>`;clearInputs();setTimeout(()=>focusFirst(),20);}
function closeModal(resumeBattle=true){bindingCapture=null;$('#modal-root').innerHTML='';S.padEditing=false;clearInputs();if(resumeBattle)setBattlePaused(false);}
function focusables(){const root=S.intro?$('#intro'):$('#modal-root').children.length?$('#modal-root'):S.dialogue?$('#story-dialogue'):S.storyActive?$('#story'):S.battle?$('#battle'):$('#main');return $$('button:not(:disabled),input:not([readonly]),select,a[href]',root).filter(e=>e.offsetWidth>0&&e.offsetHeight>0);}
function focusFirst(){const f=focusables();if(f.length)f[0].focus();}
function navigateFocus(direction){const list=focusables();if(!list.length)return;const current=document.activeElement;let idx=list.indexOf(current);if(idx<0){list[0].focus();return;}const rect=current.getBoundingClientRect(),cx=rect.x+rect.width/2,cy=rect.y+rect.height/2;let best=null,bestScore=Infinity;for(const el of list){if(el===current)continue;const r=el.getBoundingClientRect(),dx=r.x+r.width/2-cx,dy=r.y+r.height/2-cy;const forward=direction==='right'?dx:direction==='left'?-dx:direction==='down'?dy:-dy,side=(direction==='up'||direction==='down')?Math.abs(dx):Math.abs(dy);if(forward<5)continue;const score=forward+side*2.5;if(score<bestScore){best=el;bestScore=score;}}(best||list[(idx+(direction==='up'||direction==='left'?-1:1)+list.length)%list.length]).focus();}
function back(){if(S.intro)return;if(bindingCapture){cancelBinding();return;}if($('#controls-return')){returnFromControls();return;}if(S.dialogue){closeDialogue();return;}if(S.storyActive&&!$('#modal-root').children.length){storyMenu();return;}if($('#modal-root').children.length){if(!S.resultShown)closeModal();return;}if(S.battle){battleMenu();return;}if(S.room){leaveRoom();return;}if(S.view!=='home')render('home');}
function setBattlePaused(paused){if(!S.battle||['friend','demo'].includes(S.battle.mode))return;const next=Boolean(paused);if(next&&S.resultShown)return;if(S.battlePaused===next)return;S.battlePaused=next;if(next){S.keys.clear();if(S.input){S.input.dx=0;S.input.dy=0;S.input.cast=null;S.input.m1=false;S.input.dodge=false;S.input.switch=null;}}send({type:'pause',paused:next});}
function battleMenu(){if(S.resultShown)return;const canPause=!!S.battle&&!['friend','demo'].includes(S.battle.mode);if(canPause)setBattlePaused(true);const message=canPause?'Battle paused. Pokémon, rivals, damage, and the zone are frozen until you return.':'This online battle continues while the menu is open.';openModal(`<div class="result-sub">${esc(S.battle?.mode==='friend'?'PRIVATE MATCH':'ARENA BATTLE')}</div><h2>TAKE A BREATH.</h2><p>${message}</p><div class="modal-actions"><button class="primary-button" data-close-modal>RETURN TO BATTLE</button><button class="secondary-button" id="battle-controls">CONTROLS</button><button class="secondary-button" id="quit-battle">LEAVE MATCH</button></div>`);}
function connectionStatus(connected,label){$('#connection-dot').classList.toggle('online',connected);$('#connection-text').textContent=label||(connected?'STADIUM ONLINE · READY TO PLAY':'STADIUM OFFLINE');}
function send(msg){if(S.socket?.readyState===WebSocket.OPEN){S.socket.send(JSON.stringify(msg));return true;}return false;}
async function connect(origin=location.origin){const invite=typeof origin==='object'&&origin.online?origin:null;origin=invite?`online:${invite.code}:${invite.token}`:origin;if(S.connected&&S.serverOrigin===origin)return;const epoch=++S.connectionEpoch;clearTimeout(S.reconnectTimer);if(S.socket){S.socket.onclose=null;S.socket.close();}S.connected=false;S.serverOrigin=origin;connectionStatus(false,'CONNECTING TO STADIUM');return new Promise((resolve,reject)=>{let settled=false;let ws;if(invite)ws=connectOnline(invite,{onStatus:status=>connectionStatus(false,status)});else{const url=new URL('/ws',origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';ws=new WebSocket(url);}S.socket=ws;const timeout=setTimeout(()=>{if(!settled){settled=true;reject(new Error('The host did not respond. Check the invite and keep the host game open.'));ws.close();}},invite?30000:10000);ws.onopen=()=>ws.send(JSON.stringify({type:'hello',name:S.trainer}));ws.onmessage=e=>{if(epoch!==S.connectionEpoch)return;let m;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='hello'){S.connected=true;connectionStatus(true);clearTimeout(timeout);if(m.campaign){S.campaign=m.campaign;if(S.view==='circuit')renderCircuit();}if(!settled){settled=true;resolve();}}handleMessage(m);};ws.onerror=()=>{connectionStatus(false,'CONNECTION UNAVAILABLE');if(!settled){settled=true;clearTimeout(timeout);reject(new Error('Could not connect to the Stadium host.'));}};ws.onclose=()=>{if(epoch!==S.connectionEpoch)return;S.connected=false;connectionStatus(false);clearTimeout(timeout);if(!settled){settled=true;reject(new Error('The Stadium connection closed.'));}if(S.battle&&!S.resultShown){openModal('<div class="result-sub">CONNECTION LOST</div><h2>THE SIGNAL DROPPED.</h2><p>The connection to the host closed. Your local lineup is saved.</p><div class="modal-actions"><button class="primary-button" id="quit-battle">RETURN TO STADIUM</button></div>');}else if(S.room){closeOnlineRoom();S.room=null;S.inviteOrigin=null;render('private');toast('The room closed because the host connection was lost.');}else if(!S.battle&&!S.room&&origin===location.origin){S.reconnectTimer=setTimeout(()=>connect(origin).catch(()=>{}),3000);}};});}
function handleMessage(m){switch(m.type){case'room':S.room=m;S.view='private';openOnlineRoom(m);if(!S.inviteOrigin&&window.stadium&&m.host)window.stadium.getInfo().then(info=>{if(info.addresses?.length){const addr=info.addresses.find(a=>!String(a).includes('127.0.0.1'))||info.addresses[0];S.inviteOrigin=String(addr).startsWith('http')?String(addr):`http://${addr}:${info.port}`;if(S.room&&!S.battle)renderLobby();}}).catch(()=>{});render('private');break;case'battleStart':startBattle(m);break;case'state':if(S.battle){S.previousSnapshot=S.snapshot;S.snapshot=m;S.lastSnapshot=performance.now();processEvents(m);}break;case'result':showResult(m);break;case'story':setStoryData(m.story);break;case'campaign':S.campaign=m.campaign||m;if(S.view==='circuit')renderCircuit();break;case'pong':S.latency=Math.max(0,Date.now()-m.at);break;case'error':toast(m.message||m.error||'The host could not complete that action.');closeModal();if(!S.battle)render(S.view);break;case'notice':toast(m.text||m.message||'');break;case'roomClosed':closeOnlineRoom();S.room=null;toast('The host closed this room.');render('private');break;}}
async function startCpu(stage,arena=S.arena){closeOnlineRoom();closeModal();openModal('<div class="loading-ball"></div><h2>STEPPING INTO THE ARENA</h2><p>Your team is getting ready…</p>');try{await connect(location.origin);send({type:'startCpu',team:S.team,stage,arena});}catch(e){closeModal();toast(e.message);}}
async function startBattleRoyale(){const species=mon(S.brPokemonId);if(!species?.battleRoyaleStarter){toast('Choose a first-stage Pokémon that can evolve.');render('royale');return;}const preset=S.team.find(t=>t.species===species.id),legal=(preset?.moves||species.moves||[]).filter((id,i,a)=>S.moves[id]&&(species.learnset||species.moves).includes(id)&&a.indexOf(id)===i).slice(0,4);S.arena=$('#br-arena')?.value||S.arena;persist();closeOnlineRoom();closeModal();openModal('<div class="loading-ball"></div><h2>ENTERING THE WILD</h2><p>Preparing 11 rivals and your level 5 starter…</p>');try{await connect(location.origin);send({type:'startBattleRoyale',pokemon:{species:species.id,moves:legal.length?legal:[...(species.moves||[])].slice(0,4)},arena:S.arena});}catch(e){closeModal();toast(e.message);}}
function leaveRoom(){closeOnlineRoom();send({type:'leave'});S.room=null;S.inviteOrigin=null;render('private');}
function leaveBattle(destination='home'){closeOnlineRoom();if(typeof destination!=='string')destination='home';clearTimeout(notice.timer);$('#combat-notice').textContent='';$('#combat-notice').classList.remove('show');send({type:'leave'});S.battlePaused=false;combat.reset(null);S.battle=null;S.snapshot=null;S.previousSnapshot=null;S.room=null;S.resultShown=false;S.keys.clear();S.particles=[];S.rings=[];S.labels=[];for(const el of S.sprites.values())el.remove();S.sprites.clear();closeModal();$('#battle').classList.add('hidden');if(destination==='story')enterStory();else render('home');connect(location.origin).catch(()=>{});fetchCampaign();}
async function fetchCampaign(){try{const r=await fetch('/api/campaign');if(r.ok)S.campaign=await r.json();}catch{}}
function startBattle(m){stopDemo();S.lockOn=true;S.lockTargetTeam=null;storyWorld.setActive(false);S.storyActive=false;closeDialogue();$('#story').classList.add('hidden');const stage=S.campaign.stages.find(x=>x.id===m.stage);AUDIO.setContext(m.stage==='champion'?'champion':stage?.kind==='elite'?'elite':m.mode==='campaign'?'gym':'battle');clearTimeout(notice.timer);$('#combat-notice').textContent='';$('#combat-notice').classList.remove('show');closeModal();combat.reset(m);S.battle=m;S.battlePaused=false;S.snapshot=null;S.previousSnapshot=null;S.selfTeam=m.selfTeam||0;S.room=null;S.resultShown=false;S.battleStarted=performance.now();S.lastSnapshot=0;S.seenEvents.clear();S.particles=[];S.rings=[];S.labels=[];S.keys.clear();for(const e of S.sprites.values())e.remove();S.sprites.clear();$('#sprite-layer').innerHTML='';$('#app').classList.add('hidden');$('#battle').classList.remove('hidden');$('#battle').dataset.mode=m.mode;$('#battle-name').textContent=(ARENAS.find(a=>a.id===m.arena?.id)?.name||m.arena?.id||'STADIUM').toUpperCase();$('#battle-subtitle').textContent=m.mode==='campaign'?'STORY MODE':m.mode==='friend'?'PRIVATE BATTLE':m.mode==='battle-royale'?'BATTLE ROYALE · EVOLVE TO SURVIVE':'QUICK BATTLE';S.input={dx:0,dy:0,aimX:S.selfTeam?200:1000,aimY:380,cast:null,m1:false,lockOn:S.lockOn,dodge:false,switch:null};S.gamepadAim={x:S.selfTeam?-1:1,y:0};ensureArena(m.arena?.id||S.arena);$('#countdown').textContent='GO!';setTimeout(()=>{$('#countdown').textContent='';},1100);updateBattleHud(true);}
function showResult(m){if(m.story)setStoryData(m.story);if(S.battle?.mode==='campaign'){showStoryResult(m);return;}if(!S.battle||S.resultShown)return;S.resultShown=true;S.input.dx=0;S.input.dy=0;S.keys.clear();if(m.campaign)S.campaign=m.campaign;if(m.error)toast(m.error,8000);const battleRoyale=S.battle.mode==='battle-royale',won=m.selfWon??m.winner===S.selfTeam,time=Math.floor((performance.now()-S.battleStarted)/1000),self=S.snapshot?.benches?.[S.selfTeam]||[],remaining=self.filter(x=>x.hp>0).length,kills=S.snapshot?.eliminations?.[S.selfTeam]||0,level=S.snapshot?.fighters?.find(f=>f.team===S.selfTeam)?.level||5,survivors=S.snapshot?.remaining??1,reason=String(m.reason||'').replace(/[_-]/g,' ');if(won)AUDIO.win();else AUDIO.setContext('menu');const modeName=battleRoyale?'BATTLE ROYALE':S.battle.mode==='friend'?'PRIVATE BATTLE':'QUICK BATTLE',headline=m.winner===null?'A WORTHY DRAW.':won?(battleRoyale?'LAST MON STANDING!':'THE ARENA IS YOURS.'):'EVERY BATTLE TEACHES.';openModal(`<div class="result-emblem">${won?'✧':'◈'}</div><div class="result-sub">${modeName} · MATCH COMPLETE</div><h2>${headline}</h2><p>${won?(battleRoyale?'You survived all 11 rivals. The arena is yours!':'Your team held the field. A well-earned victory.'):(battleRoyale?'You were eliminated. Learn from the fight and try a new starter.':'Regroup, rethink your lineup, and take another shot.')}${reason&&reason!=='knockout'?` ${esc(reason.charAt(0).toUpperCase()+reason.slice(1))}.`:''}</p><div class="result-stats"><div class="result-stat"><strong>${Math.floor(time/60)}:${String(time%60).padStart(2,'0')}</strong><span>MATCH TIME</span></div><div class="result-stat"><strong>${battleRoyale?kills:remaining}</strong><span>${battleRoyale?'ELIMINATIONS':'STILL STANDING'}</span></div><div class="result-stat"><strong>${battleRoyale?level:(S.campaign.badges?.length||0)}</strong><span>${battleRoyale?'FINAL LEVEL':'GYM BADGES'}</span></div></div><div class="modal-actions"><button class="secondary-button" id="result-home">MAIN MENU</button><button class="primary-button" id="result-next">PLAY AGAIN ↗</button></div>`,true);$('#result-home').onclick=leaveBattle;$('#result-next').onclick=()=>{const mode=S.battle.mode;leaveBattle();render(mode==='battle-royale'?'royale':'quick');};}

const canvas=$('#arena');
const combat=new CombatRenderer({canvas,overlay:$('#sprite-layer'),species:id=>mon(id),moves:id=>S.moves[id],settings:()=>S.settings,audio:AUDIO,notice});
const demoCombat=new CombatRenderer({canvas:$('#menu-arena'),overlay:$('#menu-sprites'),species:id=>mon(id),moves:id=>S.moves[id],settings:()=>({...S.settings,screenShake:false}),audio:SILENT_AUDIO,notice:()=>{}});
const storyWorld=new StoryWorld({canvas:$('#story-world'),species:id=>mon(id),manifest:()=>combat.manifest,onInteract:talkToNpc,onTravel:p=>{if(S.connected&&S.serverOrigin===location.origin)send({type:'travel',...p});},onRegion:region=>{updateStoryHud();updateStopCard();},onLocked:message=>toast(message,2500)});
function dismissIntro(){if(!S.catalog||!S.intro)return;S.intro=false;S.inputReadyAt=performance.now()+400;S.keys.clear();AUDIO.unlock();AUDIO.setContext('menu');$('#intro').classList.add('dismissed');setTimeout(()=>{if(!S.storyActive&&!S.battle)focusFirst();},450);}
function startDemo(){if(S.demoSocket||S.view!=='home'||S.battle)return;const url=new URL('/ws',location.origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';const ws=new WebSocket(url);S.demoSocket=ws;let requested=false;ws.onopen=()=>ws.send(JSON.stringify({type:'hello',name:'Exhibition'}));ws.onmessage=e=>{if(S.demoSocket!==ws)return;let m;try{m=JSON.parse(e.data);}catch{return;}if(m.type==='hello'){if(requested)return;requested=true;if(m.local===false){stopDemo();return;}ws.send(JSON.stringify({type:'watchDemo',arena:'ruins'}));}else if(m.type==='battleStart'){S.demo={battle:m,state:null,previous:null};demoCombat.reset(m);}else if(m.type==='state'&&S.demo){S.demo.previous=S.demo.state;S.demo.state=m;demoCombat.applySnapshot(m,S.demo.previous,performance.now());}else if(m.type==='result'){clearTimeout(S.demoTimer);S.demoTimer=setTimeout(()=>{if(ws.readyState===WebSocket.OPEN&&S.view==='home')ws.send(JSON.stringify({type:'watchDemo',arena:ARENAS[Math.floor(Math.random()*ARENAS.length)].id}));},2200);}};ws.onclose=()=>{if(S.demoSocket===ws){S.demoSocket=null;S.demoTimer=setTimeout(startDemo,4500);}};ws.onerror=()=>{};}
function stopDemo(){clearTimeout(S.demoTimer);const ws=S.demoSocket;S.demoSocket=null;if(ws){ws.onclose=null;ws.close();}S.demo=null;demoCombat.reset(null);}
function setStoryData(data){if(!data?.world)return;S.storyData=data;storyWorld.setData(data);updateStoryHud();}
async function enterStory(){closeModal();stopDemo();try{await connect(location.origin);if(!S.storyData){const response=await fetch('/api/story');if(!response.ok)throw Error('Story Mode runs on the host PC. Join your friend through Private Battle.');setStoryData(await response.json());}S.view='story';S.storyActive=true;$('#story').classList.add('path-map');S.keys.clear();S.worldInput={x:0,y:0};$('#app').classList.add('hidden');$('#battle').classList.add('hidden');$('#story').classList.remove('hidden');storyWorld.setCompanion(S.team[0].species);storyWorld.setActive(true);storyWorld.lastSentPosition=null;AUDIO.setContext('story');updateStoryHud();updateStopCard();if(!S.storyData.progress.introSeen&&!S.dialogue)openDialogue('intro',S.storyData.world.npcs.find(n=>n.id==='oak'));}catch(e){toast(e.message);render('home');}}
function updateStoryHud(){const data=S.storyData;if(!data)return;const p=data.progress;$('#story-badges').textContent=`${p.badges?.length||0} / 8 BADGES`;$('#story-chapter').textContent=String(p.chapter||'THE MIDNIGHT CIRCUIT').toUpperCase();$('#story-location').textContent=(storyWorld.lastRegion?.name||data.world.regions.find(r=>r.id===p.currentRegion)?.name||'PALLET TOWN').toUpperCase();$('#story-objective-text').textContent=p.objective||'Follow the lantern road.';}
function updateStopCard(){if(!S.storyData||!storyWorld.lastRegion)return;const region=storyWorld.lastRegion,npc=storyWorld.nearestNpc,stage=S.campaign.stages.find(s=>s.id===region.stage),done=S.storyData.progress.completed.includes(region.stage),trainer=(S.catalog.trainers||[]).find(t=>t.id===npc?.portrait),portrait=npc?.portrait==='empress'?'/assets/story/empress-champion.png':trainer?.sprite;$('#story-stop-card').innerHTML=`<div class="stop-kicker">STOP ${String(storyWorld.selected).padStart(2,'0')} / 15 · ${done?'CLEARED':region.stage?'NEXT CHALLENGE':'HOME'}</div>${portrait?`<img class="stop-portrait ${npc?.portrait==='empress'?'empress':''}" src="${esc(portrait)}" alt="${esc(npc?.name)}">`:''}<h2>${esc(npc?.name||region.name)}</h2><p>${esc(stage?.title||'Your journey along the Midnight Circuit begins here.')}</p><button class="primary-button" id="story-talk">${region.stage?done?'REVISIT TRAINER':'VISIT & CHALLENGE':'SPEAK TO OAK'} →</button><div class="stop-navigation"><button class="secondary-button" id="map-prev" ${storyWorld.selected===0?'disabled':''}>← PREVIOUS</button><button class="secondary-button" id="map-next" ${!S.storyData.world.regions[storyWorld.selected+1]||!storyWorld.regionOpen(S.storyData.world.regions[storyWorld.selected+1].id)?'disabled':''}>NEXT →</button></div><small>${storyWorld.selected===15?'The crown awaits.':done||!region.stage?'Continue to the next open stop, or revisit an earlier challenge.':'Win this challenge to open the next stop.'}</small>`;}
function showRegionTitle(region){clearTimeout(showRegionTitle.timer);const node=$('#story-transition');node.querySelector('span').textContent=region.kind==='champion'?'THE MOON COURT':region.kind==='home'?'WHERE THE JOURNEY BEGINS':region.kind==='elite'?'THE POKÉMON LEAGUE':'THE MIDNIGHT CIRCUIT';node.querySelector('h2').textContent=region.name;node.classList.remove('hidden');showRegionTitle.timer=setTimeout(()=>node.classList.add('hidden'),2300);}
function talkToNpc(npc){if(S.dialogue)return;const completed=S.storyData.progress.completed.includes(npc.stage);openDialogue(completed?npc.afterDialogue||npc.dialogue:npc.dialogue,npc,!!npc.stage);}
function openDialogue(id,npc=null,challenge=false,onComplete=null){const definition=S.storyData?.dialogues?.[id];if(!definition){if(challenge&&npc?.stage)showStoryChallenge(npc);else onComplete?.();return;}S.dialogue={id,definition,npc,challenge,line:0,onComplete};S.keys.clear();S.worldInput={x:0,y:0};drawDialogue();}
function drawDialogue(){const d=S.dialogue;if(!d)return;const last=d.line>=d.definition.lines.length-1,isEmpress=d.npc?.portrait==='empress'||d.definition.speaker==='Empress';const trainer=(S.catalog.trainers||[]).find(t=>t.id===d.npc?.portrait),portrait=isEmpress?'/assets/story/empress-champion.png':trainer?.sprite;$('#story-dialogue').classList.remove('hidden');$('#story-dialogue').innerHTML=`${portrait?`<img class="dialogue-portrait ${isEmpress?'empress':''}" src="${esc(portrait)}" alt="${esc(d.definition.speaker)}">`:''}<div class="dialogue-copy"><span class="dialogue-eyebrow">${esc(d.definition.title||'THE MIDNIGHT CIRCUIT')}</span><h3 class="dialogue-speaker">${esc(d.definition.speaker||d.npc?.name||'Your journey')}</h3><p class="dialogue-text">${esc(d.definition.lines[d.line])}</p><div class="dialogue-footer"><span class="dialogue-progress">${d.line+1} / ${d.definition.lines.length}</span><div class="dialogue-actions"><button id="dialogue-next" class="primary-button">${last?(d.challenge?'VIEW CHALLENGE':'CONTINUE'):'NEXT'} <span>Ⓐ / ENTER</span></button></div></div></div>`;$('#dialogue-next').onclick=advanceDialogue;if(S.controller)$('#dialogue-next').focus();}
function advanceDialogue(){const d=S.dialogue;if(!d)return;AUDIO.click();if(d.line<d.definition.lines.length-1){d.line++;drawDialogue();return;}send({type:'storyDialogue',id:d.id});if(d.id==='intro')S.storyData.progress.introSeen=true;const challenge=d.challenge,npc=d.npc,complete=d.onComplete;closeDialogue();if(challenge)showStoryChallenge(npc);else complete?.();}
function closeDialogue(){S.dialogue=null;$('#story-dialogue').classList.add('hidden');$('#story-dialogue').innerHTML='';S.keys.clear();S.worldInput={x:0,y:0};}
function showStoryChallenge(npc){const stage=S.campaign.stages.find(x=>x.id===npc?.stage);if(!stage)return;const done=S.campaign.completed.includes(stage.id);openModal(`<div class="result-sub">${esc(stage.kind.toUpperCase())} · ${esc(storyWorld.lastRegion?.name||'STORY MODE')}</div><h2>${esc(stage.name)}</h2><p>${esc(stage.title)}<br>Your team will be fully restored before the challenge.</p><div class="result-team">${stage.team.map(id=>`<div>${imageMon(id)}<span>${esc(mon(id)?.name)}</span></div>`).join('')}</div><div class="modal-actions"><button class="secondary-button" data-close-modal>RETURN TO MAP</button><button class="primary-button" id="story-challenge">${done?'REMATCH':'CHALLENGE'} →</button></div>`);$('#story-challenge').onclick=()=>{S.storyReturn={stage:stage.id,npc,position:{x:storyWorld.player.x,y:storyWorld.player.y}};storyWorld.savePosition(true);closeModal();startCpu(stage.id,stage.arena);};}
function storyMenu(){if(S.dialogue)return;storyWorld.savePosition(true);openModal(`<div class="result-sub">STORY MODE · PROGRESS SAVED</div><h2>The road is waiting.</h2><p>${esc(S.storyData?.progress.objective||'Your next chapter awaits.')}</p><div class="modal-actions"><button class="primary-button" data-close-modal>RETURN TO MAP</button><button class="secondary-button" id="story-controls-button">CONTROLS</button><button class="secondary-button" id="story-team">YOUR TEAM</button><button class="secondary-button" id="story-home">MAIN MENU</button></div>`);$('#story-home').onclick=()=>{closeModal();render('home');};$('#story-team').onclick=()=>{closeModal();render('team');};}
function showWorldMap(){const w=S.storyData.world;openModal(`<div class="result-sub">THE MIDNIGHT CIRCUIT</div><h2>A road to the crown.</h2><div class="world-map"><img src="/assets/story/region-map.png" alt="The region from Pallet Town to the Moon Court">${w.regions.map(r=>`<span title="${esc(r.name)}" style="left:${r.x/w.width*100}%;top:${r.y/w.height*100}%;opacity:${storyWorld.regionOpen(r.id)?1:.3}">${S.storyData.progress.completed.includes(r.stage)?'◆':'●'}</span>`).join('')}<b style="left:${storyWorld.player.x/w.width*100}%;top:${storyWorld.player.y/w.height*100}%">YOU</b></div><p>${esc(S.storyData.progress.objective)}</p><div class="modal-actions"><button class="primary-button" data-close-modal>RETURN TO THE ROAD</button></div>`,true);}
function showStoryResult(m){if(!S.battle||S.resultShown)return;if(m.error)toast(m.error,10000);S.resultShown=true;S.keys.clear();S.input.dx=0;S.input.dy=0;if(m.campaign)S.campaign=m.campaign;const won=m.selfWon??m.winner===S.selfTeam,stage=S.battle.stage,savedWin=won&&!m.error,champion=stage==='champion'&&savedWin,npc=S.storyReturn?.npc||S.storyData?.world.npcs.find(n=>n.stage===stage);AUDIO.setContext(won?(champion?'championVictory':'victory'):'story');openModal(`${champion?'<img class="empress-result-portrait" src="/assets/story/empress-champion.png" alt="Champion Empress">':''}<div class="result-sub">${champion?'HALL OF FAME':m.error?'PROGRESS NOT SAVED':savedWin?'CHAPTER COMPLETE':'THE JOURNEY CONTINUES'}</div><h2>${m.error?'Your victory needs saving.':champion?'A crown, earned.':savedWin?'Another lantern lit.':'Stand up. Try again.'}</h2><p>${m.error?esc(m.error)+' Your saved route is unchanged; return to the trainer to retry the challenge.':champion?'Empress recognizes you as a Champion. Your companions have carried you to the end of the Midnight Circuit.':won?'The road ahead has opened. Speak with your opponent, then follow the lanterns toward your next challenge.':'Your team is restored. Adjust your lineup and select this stop when you are ready.'}</p><div class="result-team">${S.team.map(t=>`<div>${imageMon(t.species)}<span>${esc(mon(t.species).name)}</span></div>`).join('')}</div><div class="result-stats"><div class="result-stat"><strong>${S.campaign.badges?.length||0} / 8</strong><span>GYM BADGES</span></div><div class="result-stat"><strong>${S.campaign.completed?.length||0} / 15</strong><span>CHALLENGES CLEARED</span></div></div><div class="modal-actions"><button class="primary-button" id="story-result-continue">${champion?'ENTER THE HALL OF FAME':'RETURN TO YOUR JOURNEY'} →</button></div>`,true);$('#story-result-continue').onclick=async()=>{leaveBattle('story');await connect(location.origin);const after=()=>{if(champion&&!S.storyData.progress.endingSeen)openDialogue('ending',npc);};openDialogue(savedWin?(npc?.afterDialogue||`${stage}-after`):'lost-battle',npc,false,after);};}

function ensureArena(id){combat.loadArena(id);}
function worldPosition(clientX,clientY){const r=canvas.getBoundingClientRect();return combat.screenToWorld((clientX-r.left)/r.width*1200,(clientY-r.top)/r.height*760);}
function selfFighter(){return S.snapshot?.fighters?.find(f=>f.team===S.selfTeam);}
function enemyFighter(){return S.snapshot?.fighters?.find(f=>f.team!==S.selfTeam);}
function currentPokemon(team,slot){return S.battle?.teams?.[team]?.pokemon?.[slot];}
function processEvents(state){combat.applySnapshot(state,S.previousSnapshot,performance.now());}
function drawArena(now,dt){combat.render(S.battle,S.snapshot,now,dt,{selfTeam:S.selfTeam,aimX:S.input.aimX,aimY:S.input.aimY,resultShown:S.resultShown,lockTargetTeam:S.lockTargetTeam});}
function fighterHud(f,enemy=false){if(!f)return '';const trainer=S.battle.teams?.[f.team]?.name|| (enemy?'CPU TRAINER':S.trainer),ratio=clamp(f.hp/f.maxHp*100,0,100),xp=f.xp||0;return `<div class="hud-trainer"><span>${esc(trainer.toUpperCase())}</span><span>Lv. ${f.level||50}</span></div><div class="hud-name">${esc(f.name)}<span class="hud-type">${chips(f.types)}</span></div><div class="hud-hp"><i style="width:${ratio}%;${ratio<25?'background:#ee9387':''}"></i></div><div class="hud-values"><span>${Math.max(0,Math.ceil(f.hp))} / ${f.maxHp} HP</span><span class="status-tags">${f.status?`<span class="status-tag">${esc(f.status)}</span>`:''}${f.protect?'<span class="status-tag">PROTECTED</span>':''}${f.dodge?'<span class="status-tag">DODGING</span>':''}</span></div><div class="hud-ability">${esc(f.ability||'')}${f.ability&&!f.abilityImplemented?' · INACTIVE':''}</div>${S.battle.mode==='battle-royale'?`<div class="br-xp"><span>${(f.level||5)>=100?'MAX LEVEL':`${xp} XP · NEXT LEVEL IN ${60-xp%60}`}</span><i><b style="width:${(f.level||5)>=100?100:clamp(xp%60/60*100,0,100)}%"></b></i><span>${f.evolution?`EVOLVING → ${esc(mon(f.evolution.toSpecies)?.name||f.evolution.toSpecies)}`:f.nextEvolutionLevel?`EVOLUTION AT LEVEL ${f.nextEvolutionLevel}`:'FINAL FORM'}</span></div>`:''}`;}
function updateBattleHud(force=false){if(!S.battle)return;const state=S.snapshot,self=selfFighter(),enemy=enemyFighter();if(!self){$('#fighter-hud').innerHTML='';$('#enemy-hud').innerHTML='';$('#moves-hud').innerHTML='';$('#team-hud').innerHTML='';return;}$('#fighter-hud').innerHTML=fighterHud(self);$('#enemy-hud').innerHTML=S.battle.mode==='battle-royale'?`<div class="hud-trainer"><span>BATTLE ROYALE</span><span>${state?.remaining??0} LEFT</span></div><div class="hud-name">SURVIVORS <strong>${state?.remaining??0}</strong></div><div class="hud-values"><span>ELIMINATIONS ${state?.eliminations?.[S.selfTeam]||0}</span><span>${Math.floor(state?.time||0)}s</span></div><div class="hud-ability">${state?.zone?.closing?'ZONE CLOSING':state?.zone?.timeToStart>0?`ZONE IN ${Math.ceil(state.zone.timeToStart)}s`:'FINAL ZONE'}</div>`:fighterHud(enemy,true);const keys=S.controller?['A','X','Y','B']:[1,2,3,4].map(i=>keyLabel(`move${i}`));$('#moves-hud').innerHTML=(S.battle.mode==='battle-royale'?'<button class="move-card m1-card" data-m1="1" aria-label="M1 Scratch, click for a close attack" title="M1 · SCRATCH · close-range attack"><span class="key">M1</span><span class="move-type">NORMAL</span><span class="move-name">SCRATCH</span><span class="move-pp">'+((self.m1Cooldown||0)>.02?`READY IN ${(self.m1Cooldown).toFixed(1)}s`:'NO PP · CLICK')+'</span></button>':'')+Array.from({length:4},(_,i)=>{const id=self.moves[i],original=S.moves[id]||currentPokemon(self.team,self.slot)?.moves?.[i],pp=self.pp?.[i]??original?.pp,empty=pp<=0,m=empty?S.moves.struggle:original;if(!m)return `<div class="move-card depleted" style="--type:#8590a6"><span class="key">${keys[i]}</span><span class="move-name">—</span><span class="move-pp">NO LEGAL MOVE</span></div>`;const remaining=self.cooldowns?.[i]||0,max=m.arena?.cooldown||m.cooldown||4,percent=clamp(remaining/max,0,1)*100;return `<button class="move-card ${remaining>0?'cooling':''} ${empty?'struggle':''}" data-cast="${i}" style="--type:${color(m.type)}" aria-label="${esc(empty?`Struggle, ${original.name} has no PP`:m.name)}" title="${esc(empty?`${original.name}: 0 PP. Struggle is a close-range attack with recoil. Collect a PP orb to restore a move.`:m.name)}"><span class="key">${esc(keys[i])}</span><span class="move-type">${empty?'TYPELESS':esc(m.type.toUpperCase())}</span><span class="move-name">${esc(m.name)}</span><span class="move-pp">${empty?'NO PP NEEDED · RECOIL':`${pp} / ${self.maxPp?.[i]||m.pp} PP · ${m.category==='Status'?'STATUS':m.category?.toUpperCase()||'MOVE'}`}</span>${remaining>.05?`<div class="cooldown-fill" style="height:${percent}%"></div><span class="cooldown-number">${remaining.toFixed(1)}</span>`:''}</button>`;}).join('');const team=state.benches?.[S.selfTeam]||[];$('#team-hud').innerHTML=team.map((p,i)=>`<button class="team-chip ${i===self.slot?'active':''} ${p.hp<=0?'fainted':''}" data-switch="${i}" aria-label="Switch to ${esc(p.name)}" ${p.hp<=0?'disabled':''}><small>${i+1}</small>${imageMon(p.species)}<span><i style="width:${clamp(p.hp/p.maxHp*100,0,100)}%"></i></span></button>`).join('');$('#dodge-key').textContent=S.controller?'RT':keyLabel('dodge');$('#dodge-ready').style.width=`${clamp(1-(self.dodgeCooldown||0)/2.8,0,1)*100}%`;$('#battle-hints').innerHTML=S.controller?'LEFT STICK MOVE & FACE <span>·</span> A/X/Y/B ATTACK <span>·</span> RT DODGE <span>·</span> LB/RB SWITCH':keyboardHints();const elapsed=state.time??(performance.now()-S.battleStarted)/1000;$('#battle-clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;$('#battle-net').textContent=S.connected?`${S.latency?S.latency+' MS · ':''}LIVE`:'OFFLINE';}
function cast(slot){if(!S.battle||S.resultShown||$('#modal-root').children.length)return;const f=selfFighter();if(!f?.moves?.[slot])return;S.input.cast=slot;}
