function menuPad(pad,pressed,just,dead,now){if(just(0)){const e=document.activeElement;if(e?.tagName==='SELECT'||e?.type==='range'){S.padEditing=!S.padEditing;if(!S.padEditing)navigateFocus('down');else toast('Adjust with the stick. Press A to confirm.',1800);}else if(e&&e!==document.body)e.click();else focusFirst();}if(just(1)){if(S.padEditing)S.padEditing=false;else back();}const x=dead(pad.axes[0]||0),y=dead(pad.axes[1]||0);const direction=pressed[12]||y<-.5?'up':pressed[13]||y>.5?'down':pressed[14]||x<-.5?'left':pressed[15]||x>.5?'right':null;if(direction&&now-S.padNavAt>180){const el=document.activeElement;if(el?.tagName==='SELECT'&&S.padEditing){el.selectedIndex=clamp(el.selectedIndex+(direction==='up'||direction==='left'?-1:1),0,el.options.length-1);el.dispatchEvent(new Event('change',{bubbles:true}));}else if(el?.type==='range'&&S.padEditing){el.value=clamp(+el.value+(['left','down'].includes(direction)?-5:5),0,100);el.dispatchEvent(new Event('input',{bubbles:true}));}else navigateFocus(direction);S.padNavAt=now;}}
