function frame(now){const dt=Math.min(.05,(now-S.lastRender)/1000||.016);S.lastRender=now;pollGamepad(now);if(S.battle){updateAim();drawArena(now,dt);if(now-S.lastHud>100){updateBattleHud();S.lastHud=now;}}else if(S.storyActive){storyWorld.update(dt,S.worldInput,!!S.dialogue||!!$('#modal-root').children.length);storyWorld.render(now);const nearest=storyWorld.nearestNpc,interaction=$('#story-interaction');interaction.classList.add('hidden');if(nearest){interaction.querySelector('kbd').textContent=S.controller?'A':keyLabel('interact');interaction.querySelector('span').textContent=`TALK TO ${nearest.name.toUpperCase()}`;}$('#story-controls').textContent=S.controller?'LEFT / RIGHT STICK: PREVIOUS / NEXT STOP · A VISIT · MENU OPTIONS':`${keyLabel('left')} / ${keyLabel('right')} PREVIOUS / NEXT STOP · ${keyLabel('interact')} VISIT · ESC MENU`;}else if(S.view==='home'&&S.demo){const f=S.demo.state?.fighters?.[0];demoCombat.render(S.demo.battle,S.demo.state,now,dt,{selfTeam:0,aimX:(f?.x||600)+(f?.facing?.x||1)*300,aimY:(f?.y||380)+(f?.facing?.y||0)*300,resultShown:false});}requestAnimationFrame(frame);}

