document.addEventListener('click',async e=>{const btn=e.target.closest('button');if(!btn||btn.disabled)return;if(S.intro){if(btn.id==='intro-enter')dismissIntro();return;}if(performance.now()<S.inputReadyAt)return;AUDIO.click();if(btn.dataset.authMode){openAuthModal(btn.dataset.authMode);return;}if(btn.id==='auth-google'){window.location.assign('/api/auth/google');return;}if(btn.dataset.bindAction){captureBinding(btn.dataset.bindAction,+btn.dataset.bindIndex);return;}if(btn.dataset.view){if(S.room&&btn.dataset.view!=='private'){closeOnlineRoom();send({type:'leave'});S.room=null;}render(btn.dataset.view);return;}if(btn.hasAttribute('data-close-modal')){closeModal();return;}if(btn.dataset.arena){S.arena=btn.dataset.arena;persist();renderQuick();return;}if(btn.dataset.slot!==undefined){S.selectedSlot=+btn.dataset.slot;renderTeam();return;}if(btn.dataset.brPokemon){S.brPokemonId=btn.dataset.brPokemon;persist();AUDIO.cry(S.brPokemonId);renderRoyale();return;}if(btn.dataset.pokemon){const p=mon(btn.dataset.pokemon);S.team[S.selectedSlot]={species:p.id,moves:[...p.moves]};persist();AUDIO.cry(p.id);renderTeam();toast(`${p.name} is ready in slot ${S.selectedSlot+1}.`);return;}if(btn.dataset.editMove!==undefined){editMove(+btn.dataset.editMove);return;}if(btn.dataset.m1!==undefined){S.input.m1=true;return;}if(btn.dataset.cast!==undefined){cast(+btn.dataset.cast);return;}if(btn.dataset.switch!==undefined){switchPokemon(+btn.dataset.switch,true);return;}if(btn.dataset.toggle){const key=btn.dataset.toggle;S.settings[key]=!S.settings[key];btn.classList.toggle('on',S.settings[key]);btn.setAttribute('aria-checked',S.settings[key]);persist();if(key==='fullscreen'&&window.stadium)await window.stadium.setFullscreen(S.settings.fullscreen);return;}const actions={'edit-controls':()=>controlsModal('settings'),'battle-controls':()=>controlsModal('battle'),'story-controls-button':()=>controlsModal('story'),'controls-return':returnFromControls,'cancel-binding':()=>cancelBinding(),'reset-controls':()=>{S.settings.bindings=defaultBindings();persist();controlsModal();$('#binding-status').textContent='Default controls restored.';updateBattleHud(true);},'home-button':()=>render('home'),'start-quick':()=>startCpu(undefined,S.arena),'start-royale':startBattleRoyale,'lock-on-toggle':toggleLockOn,'load-more':()=>{S.gridLimit+=72;renderCatalog();},'br-load-more':()=>{S.brGridLimit+=48;renderRoyaleCatalog();},'create-room':createRoom,'join-room':joinRoom,'copy-invite':copyInvite,'retry-online':()=>{const room=S.room;closeOnlineRoom();openOnlineRoom(room);},'leave-room':leaveRoom,'arena-rules':showRules,'edit-profile':editProfile,'profile-button':openAccountModal,'edit-profile':openAccountModal,'auth-logout':signOutAccount,'battle-menu':battleMenu,'quit-battle':()=>leaveBattle(S.battle?.mode==='campaign'?'story':'home'),'intro-enter':dismissIntro,'story-menu':storyMenu,'story-talk':()=>storyWorld.interact(),'map-prev':()=>storyWorld.step(-1),'map-next':()=>storyWorld.step(1)};actions[btn.id]?.();});
document.addEventListener('submit',async e=>{
  const form=e.target;
  if(form.id==='auth-form'){
    e.preventDefault();const box=$('#auth-error'),button=form.querySelector('button[type="submit"]'),mode=form.dataset.mode;
    box.textContent='';
    const email=$('#auth-email').value.trim(),password=$('#auth-password').value;
    if(mode==='register'&&password!==$('#auth-confirm').value){box.textContent='Passwords do not match.';return;}
    button.disabled=true;button.textContent=mode==='register'?'CREATING ACCOUNT…':'SIGNING IN…';
    try{
      const response=await fetch(mode==='register'?'/api/auth/register':'/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,password,displayName:mode==='register'?$('#auth-name').value.trim():undefined})});
      const data=await response.json().catch(()=>({error:'The server returned an invalid response.'}));
      if(!response.ok)throw new Error(data.error||'Sign-in failed.');
      S.user=data.user;S.trainer=data.user.displayName||S.trainer;persist();send({type:'hello',name:S.trainer});closeModal();updateNav();toast(mode==='register'?'Your trainer account has been created.':'Welcome back, '+S.trainer+'!');
    }catch(error){if($('#auth-error'))$('#auth-error').textContent=error.message||'Could not reach the sign-in server.';}
    finally{if(button.isConnected){button.disabled=false;button.textContent=mode==='register'?'CREATE ACCOUNT':'SIGN IN';}}
    return;
  }
  if(form.id==='profile-form'){
    e.preventDefault();const box=$('#profile-error'),button=form.querySelector('button[type="submit"]'),file=$('#profile-photo')?.files?.[0];
    box.textContent='';
    if(file&&(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>256*1024)){box.textContent='Choose a PNG, JPG or WebP smaller than 256 KB.';return;}
    button.disabled=true;button.textContent='SAVING PROFILE…';
    try{
      let avatar=$('#profile-photo-remove')?.checked?'':(S.user?.avatar||'');
      if(file)avatar=await readImageData(file);
      const response=await fetch('/api/auth/profile',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({displayName:$('#profile-name').value.trim(),avatar})});
      const data=await response.json().catch(()=>({error:'The server returned an invalid response.'}));
      if(!response.ok)throw new Error(data.error||'The profile could not be saved.');
      S.user=data.user;S.trainer=data.user.displayName||S.trainer;persist();send({type:'hello',name:S.trainer});closeModal();updateNav();toast('Trainer profile saved.');
    }catch(error){if($('#profile-error'))$('#profile-error').textContent=error.message||'Could not save the profile.';}
    finally{if(button.isConnected){button.disabled=false;button.textContent='SAVE PROFILE';}}
  }
});
