async function boot(){loading();$('#intro-enter').disabled=true;try{const responses=await Promise.allSettled([fetch('/api/catalog').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json();}),fetch('/api/campaign').then(r=>r.ok?r.json():null),fetch('/api/rules').then(r=>r.ok?r.json():null),fetch('/data/movement.json').then(r=>r.ok?r.json():{}),fetch('/api/story').then(r=>r.ok?r.json():null),fetch('/api/auth/me').then(r=>r.ok?r.json():null),fetch('/api/auth/config').then(r=>r.ok?r.json():null)]);if(responses[0].status!=='fulfilled'){const fallback=await fetch('/data/catalog.json');if(!fallback.ok)throw new Error('The Pokémon catalog could not be loaded. Restart the Stadium host.');S.catalog=await fallback.json();}else S.catalog=responses[0].value;S.dex=new Map(S.catalog.species.map(p=>[p.id,p]));S.moves=S.catalog.moves;if(responses[1].status==='fulfilled'&&responses[1].value)S.campaign=responses[1].value;if(responses[2].status==='fulfilled')S.rules=responses[2].value;if(responses[3].status==='fulfilled'){combat.setManifest(responses[3].value);demoCombat.setManifest(responses[3].value);}if(responses[4].status==='fulfilled'&&responses[4].value)setStoryData(responses[4].value);if(responses[5].status==='fulfilled'&&responses[5].value?.user){S.user=responses[5].value.user;S.trainer=S.user.displayName||S.trainer;}if(responses[6].status==='fulfilled'&&responses[6].value)S.authConfig=responses[6].value;normalizeTeam();try{if(location.hash.includes('join=')||(location.search.includes('code=')||location.search.includes('room='))){S.pendingInvite=parseInvite(location.href);S.view='private';}}catch{}render(S.view);$('#intro-enter').disabled=false;await connect(location.origin).catch(e=>toast(e.message));if(window.stadium&&S.settings.fullscreen)window.stadium.setFullscreen(true).catch(()=>{});for(const arena of ARENAS)ensureArena(arena.id);requestAnimationFrame(frame);showAuthRedirectNotice();}catch(e){S.intro=false;$('#intro').classList.add('dismissed');$('#main').innerHTML=`<div class="loading-screen"><h2>THE GAME NEEDS A MOMENT.</h2><p>${esc(e.message)}</p><button class="primary-button" id="reload-app" style="margin-top:23px">TRY AGAIN</button></div>`;$('#reload-app').onclick=()=>location.reload();}}
boot();
